import {theoryCard} from './opening-study.js';
import {updateBoard} from './board-dom.js';
import {getLanguage,t} from './i18n.js';
import {hintFor,attackedSquares} from './mentor.js';
import {planContext,addWhy,summaryHTML,ENDGAMES,goals} from './coaching-tools.js';
import {gradeMove,checkedGrade} from './move-grade.js';
import {briefComment,strategicHint,coachAnswer} from './brief-coach.js';
import {saveGame,mistakeTheme,newId,getRecord} from './archive.js';
import {Chess} from './vendor/chess.js';
import {Engine,classify,terminal,TYPES} from './analysis.js';
import {scoreText} from './explanations.js';
import {LEVELS,pieceNames,hintsFor,lessonFor,undoTurn,gameOutcome} from './coach-core.js';
import {getSettings,saveSettings,avatarSVG,escapeHTML as esc,playSound} from './settings.js';
import {animateBoard} from './motion.js';
const $=id=>document.getElementById(id),engine=new Engine(s=>$('coachEngine').textContent=s);
let chess=new Chess(),human='w',level=1,flipped=false,selected=null,phase='setup',locked=false,result=null,steps=[],step=0,hint=0,token=0,lastErrorTask=null,active=false;
const quality=()=>'deep';
let sessionId=newId(),humanDetails=[],lastComment='',previousComment='',resultPromise=null,lastGrade=null,openings={},bookPromise=null;
function loadOpenings(){return bookPromise||=fetch('vendor/openings.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(v=>{openings=v}).catch(()=>message('Catalogo aperture non disponibile: Teoria non sarà assegnata.'))}
let boardSignature='',hintStep=0,hintSquares=[],showThreats=false,feedbackHistory=[];
function clearGuidance(){hintStep=0;hintSquares=[];showThreats=false;$('showThreats').setAttribute('aria-pressed','false');$('askHint').textContent='Dammi un indizio';$('hintText').textContent='';$('threatNote').textContent=''}
function renderMarks(){const squares=showThreats?attackedSquares(chess,human):[];for(const b of $('trainingBoard').querySelectorAll('[data-sq]')){b.classList.toggle('threat-mark',squares.includes(b.dataset.sq));b.classList.toggle('hint-square',hintSquares.includes(b.dataset.sq))}$('threatNote').textContent=showThreats?(squares.length?'Pezzi attaccati nella posizione attuale, anche se difesi.':'Nessun tuo pezzo attaccato nella posizione attuale.'):''}


function message(text){$('trainingMessage').hidden=!text;$('trainingMessage').textContent=text}
function refreshAvatar(){const s=getSettings();['setupAvatar','opponentAvatar','dialogueAvatar'].forEach(id=>$(id).innerHTML=avatarSVG(s));['setupName','opponentName','dialogueName'].forEach(id=>$(id).textContent=s.coachName)}
refreshAvatar();window.addEventListener('ply-settings',()=>{refreshAvatar();if(active){if(lastGrade?.move&&!(getSettings().coachFrequency==='errors'&&lastGrade.loss<=.05))lastComment=briefComment(lastGrade.move,lastGrade.before,lastGrade.after,lastGrade,getSettings().coachTone);clearGuidance();$('questionAnswer').textContent='Seleziona una domanda per ragionare sulla posizione attuale.';renderBoard();renderDialogue()}});
function save(){const outcome=gameOutcome(chess);chess.setHeader('Result',chess.isCheckmate()?(chess.turn()==='w'?'0-1':'1-0'):outcome?'1/2-1/2':'*');const entry={version:1,pgn:chess.pgn(),human,level,sessionId,humanDetails,lastGrade,lastComment,feedbackHistory};try{localStorage.setItem('plystreak-training',JSON.stringify(entry));$('saveStatus').textContent='Allenamento salvato su questo dispositivo.'}catch{$('saveStatus').textContent='Salvataggio non disponibile: esporta il PGN.'}if(chess.history().length)saveGame({id:sessionId,pgn:chess.pgn(),source:'coach',side:human,analysis:{version:2,complete:!!outcome&&humanDetails.length===chess.history({verbose:true}).filter(m=>m.color===human).length,details:humanDetails,coverage:'player',at:Date.now()}}).catch(()=>{$('saveStatus').textContent='Archivio non disponibile: esporta il PGN.'})}
function setBusy(value){locked=value;renderBoard();['undoTraining','newLesson','continueLesson','retryMove','askHint','retryEngine','reviewTraining','exportTraining'].forEach(id=>$(id).disabled=value);document.querySelectorAll('[data-question]').forEach(b=>b.disabled=value)}
function renderBoard(){const legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[],last=chess.history({verbose:true}).at(-1);let html='';for(let row=0;row<8;row++)for(let col=0;col<8;col++){const f=flipped?7-col:col,r=flipped?row:7-row,sq='abcdefgh'[f]+(r+1),p=chess.get(sq);html+=`<button class="square ${(f+r)%2===0?'dark':''} ${selected===sq?'selected':''} ${legal.includes(sq)?'legal':''} ${last&&(last.from===sq||last.to===sq)?'last':''} ${p?.type==='k'&&p.color===chess.turn()&&chess.isCheck()?'in-check':''}" data-sq="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'Bianco ':'Nero ')+pieceNames[p.type]:''}" ${locked||phase!=='user'?'disabled':''}>${p?`<img src="pieces/${p.color}${p.type.toUpperCase()}.png" alt="" draggable="false">`:''}${col===0?`<span class="coord rank">${r+1}</span>`:''}${row===7?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}const signature=chess.fen()+'|'+flipped+'|'+selected;if(signature!==boardSignature){updateBoard($('trainingBoard'),html);boardSignature=signature}for(const b of $('trainingBoard').querySelectorAll('[data-sq]'))b.disabled=locked||phase!=='user';animateBoard($('trainingBoard'),chess.fen(),flipped,{draw:chess.isDraw()});renderMarks();$('humanBadge').textContent=human==='w'?'B':'N';$('turnStatus').textContent=gameOutcome(chess)||(locked?'Il coach sta ragionando…':phase==='user'?'Tocca un tuo pezzo, poi la casa di destinazione.':'Il coach prepara la risposta.');$('trainingMoves').textContent=chess.history().map((m,i)=>(i%2===0?`${i/2+1}. `:'')+m).join(' ')||'La tua prima mossa ti aspetta.';$('undoTraining').disabled=locked||!chess.history().length;$('reviewTraining').disabled=locked||!chess.history().length;$('opponentLevel').textContent=LEVELS[level].name+' · '+(human==='w'?'Nero':'Bianco')}
function renderDialogue(){
 $('hintControls').hidden=phase!=='user'||!getSettings().coachHints;$('lessonControls').hidden=true;$('continueLesson').hidden=true;$('retryMove').hidden=true;$('retryEngine').hidden=phase!=='error';
 $('phaseBadge').textContent={setup:'Preparazione',thinking:'Il coach pensa',user:'Tocca a te',ended:'Fine partita',error:'In pausa'}[phase]||'';
 if(phase==='error')return;
 const title=phase==='ended'?(gameOutcome(chess)||'Partita conclusa'):(lastComment||lastGrade)?'La tua ultima mossa':phase==='thinking'?'Sto pensando…':'La scacchiera è tua.';
 const feedback=lastGrade?.move&&lastComment?briefComment(lastGrade.move,lastGrade.before,lastGrade.after,lastGrade,getSettings().coachTone):lastComment;
 const text=feedback||(phase==='thinking'?'Un momento: controllo la posizione.':'Scegli il tuo piano e gioca. Ti darò un riscontro breve dopo la tua mossa.');
 $('coachContent').innerHTML=`${lastGrade?`<div class="coach-grade"><img src="icons/${lastGrade.type}.svg" width="28" height="28" alt=""><strong>${esc(lastGrade.san)} · ${TYPES[lastGrade.type].label}</strong><span>Precisione ${lastGrade.accuracy.toFixed(1)}/100</span></div><p class="coach-eval">Dopo la tua mossa: ${esc(scoreText(lastGrade.after))} · dal punto di vista del Bianco</p>`:''}${lastGrade?.move?theoryCard(lastGrade.move,lastGrade,openings,chess.history({verbose:true})):''}<h3>${esc(title)}</h3><p id="feedbackText" class="coach-feedback-text">${esc(text)}</p>${text.length>180?'<button id="expandFeedback" class="text-button coach-read-more" aria-expanded="false">Leggi tutto</button>':''}${phase==='ended'?'<p>La partita è in Progressi. Puoi rivederla o allenarti sugli errori.</p>':''}`;
 if($('expandFeedback'))$('expandFeedback').onclick=()=>{const open=$('feedbackText').classList.toggle('expanded');$('expandFeedback').setAttribute('aria-expanded',String(open));$('expandFeedback').textContent=open?'Riduci':'Leggi tutto'};
 $('coachHistory').innerHTML=feedbackHistory.slice(-3).reverse().map(x=>`<p><strong>${esc(x.san)}</strong> · ${esc(x.move?briefComment(x.move,x.before,x.after,x.grade,getSettings().coachTone):t(x.text))}</p>`).join('')||'<p>I consigli delle tue prossime mosse appariranno qui.</p>';
 if(lastGrade?.move)addWhy($('coachContent'),lastGrade.move);if(phase==='ended')$('coachContent').insertAdjacentHTML('beforeend',summaryHTML(humanDetails,human));
}
async function analyze(){return terminal(chess)||await engine.evaluate(chess.fen(),quality())}
async function run(task){const id=++token;lastErrorTask=task;setBusy(true);message('');try{await task(id)}catch(e){if(id===token){phase='error';$('coachContent').innerHTML='<h3>Il motore si è fermato.</h3><p>La partita è conservata. Riprova oppure esporta il PGN.</p>';message(e.message)}}finally{if(id===token){setBusy(false);renderBoard();renderDialogue();save()}}}
async function prepareTurn(){phase='thinking';renderDialogue();await loadOpenings();result=await analyze();resultPromise=null;const history=chess.history({verbose:true}),m=history.at(-1);if(m?.color===human&&!humanDetails.some(d=>d.ply===history.length-1)){const before=await engine.evaluate(m.before,quality()),prior=history.at(-2);const previousLoss=prior?gradeMove({move:prior,before:await engine.evaluate(prior.before,quality()),after:before,openings}).loss:0;await completeHuman(m,before,result,previousLoss)}if(gameOutcome(chess)){phase='ended';return}if(chess.turn()!==human){await botTurn();return}phase='user'}
function precompute(){const fen=chess.fen();const pending=analyze();resultPromise=pending;pending.then(r=>{if(chess.fen()===fen)result=r}).catch(()=>{});}
async function botTurn(){if(gameOutcome(chess)){phase='ended';return}phase='thinking';renderDialogue();const selection=await engine.evaluate(chess.fen(),'quick','',{skill:LEVELS[level].skill,limits:LEVELS[level].limits});const u=selection.best;if(!u||u==='(none)')throw Error('Nessuna mossa ricevuta: riprova il motore.');chess.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});selected=null;playSound();result=null;phase=gameOutcome(chess)?'ended':'user';renderBoard();save();if(phase==='user')precompute();}
async function humanMove(from,to,promotion){if(locked||phase!=='user'||chess.turn()!==human)return;const candidates=chess.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!candidates.length)return;if(candidates.some(m=>m.promotion)&&!promotion){promotion=await choosePromotion();if(!promotion)return}await run(async()=>{const before=result||(resultPromise?await resultPromise:await analyze());let previousLoss=0;const previous=chess.history({verbose:true}).at(-1);if(previous){const previousBefore=await engine.evaluate(previous.before,quality());previousLoss=gradeMove({move:previous,before:previousBefore,after:before,openings}).loss}clearGuidance();resultPromise=null;lastGrade=null;previousComment=lastComment;lastComment='';const m=chess.move({from,to,promotion:promotion||'q'});selected=null;phase='thinking';renderBoard();renderDialogue();playSound();save();const after=await analyze();result=after;await completeHuman(m,before,after,previousLoss);$('hintText').textContent='';$('questionAnswer').textContent='Seleziona una domanda per ragionare sulla posizione attuale.';renderDialogue();save();if(gameOutcome(chess)){phase='ended';return}await botTurn()})}
async function completeHuman(m,before,after,previousLoss){const grade=await checkedGrade(engine,{move:m,before,after,openings,previousLoss});before=grade.reviewBefore||before;after=grade.reviewAfter||after;lastGrade={...grade,san:m.san,before,after,move:m};humanDetails.push({ply:chess.history().length-1,side:human,san:m.san,from:m.from,to:m.to,fen:m.before,afterFen:m.after,loss:grade.loss,accuracy:grade.accuracy,type:grade.type,theme:mistakeTheme(m,after),best:before.lines?.[0]?.pv[0]});lastComment=getSettings().coachFrequency==='errors'&&grade.loss<=.05?'':briefComment(m,before,after,grade,getSettings().coachTone,{previous:previousComment})+(getLanguage()!=='it'||getSettings().coachTone==='quiet'||grade.loss>.05?'':' '+planContext(chess.history({verbose:true}),human));if(lastComment){if(grade.type==='book'&&getLanguage()==='it')lastComment='Questa posizione è nel repertorio delle aperture. '+lastComment;feedbackHistory.push({ply:chess.history().length,san:m.san,text:lastComment,move:m,before,after,grade,language:getLanguage()});feedbackHistory=feedbackHistory.slice(-12)}}
function choosePromotion(){return new Promise(resolve=>{const d=$('trainingPromotion');$('trainingPromotionOptions').innerHTML=['q','r','b','n'].map(p=>`<button data-promotion="${p}" aria-label="${pieceNames[p]}"><img alt="${pieceNames[p]}" src="pieces/${human}${p.toUpperCase()}.png"></button>`).join('');const done=p=>{d.close();resolve(p)};$('trainingPromotionOptions').onclick=e=>{const b=e.target.closest('[data-promotion]');if(b)done(b.dataset.promotion)};$('cancelTrainingPromotion').onclick=()=>done(null);d.oncancel=e=>{e.preventDefault();done(null)};d.showModal()})}
function activate(){clearGuidance();document.body.classList.add('training-active');active=true;flipped=human==='b';selected=null;result=null;resultPromise=null;steps=[];step=0;phase='thinking';$('setup').hidden=true;$('training').hidden=false;$('questionAnswer').textContent='Seleziona una domanda per ragionare sulla posizione attuale.';save();renderBoard();renderDialogue();run(prepareTurn)}
$('difficulty').onchange=()=>$('difficultyDescription').textContent=LEVELS[Number($('difficulty').value)].description;$('difficulty').onchange();
$('startLesson').onclick=()=>{const training=ENDGAMES[Number($('trainingPosition').value)];chess=$('trainingPosition').value!==''&&training?new Chess(training.fen):new Chess();sessionId=newId();humanDetails=[];feedbackHistory=[];lastComment='';lastGrade=null;human=$('humanSide').value;if(human==='random')human=Math.random()<.5?'w':'b';level=Number($('difficulty').value);chess.setHeader('Event','Plystreak · Allenamento');chess.setHeader('White',human==='w'?'Tu':getSettings().coachName);chess.setHeader('Black',human==='b'?'Tu':getSettings().coachName);activate()};
function resume(){try{const s=JSON.parse(localStorage.getItem('plystreak-training'));if(!s||s.version!==1||!['w','b'].includes(s.human)||!Number.isInteger(s.level)||!LEVELS[s.level])throw Error('Salvataggio non valido.');chess=new Chess();if(s.pgn)chess.loadPgn(s.pgn);feedbackHistory=Array.isArray(s.feedbackHistory)?s.feedbackHistory.filter(x=>Number.isInteger(x.ply)&&typeof x.text==='string'&&typeof x.san==='string').slice(-12):[];human=s.human;level=s.level;sessionId=s.sessionId||newId();humanDetails=Array.isArray(s.humanDetails)?s.humanDetails:[];lastComment=typeof s.lastComment==='string'?s.lastComment:'';lastGrade=s.lastGrade&&TYPES[s.lastGrade.type]&&Number.isFinite(s.lastGrade.accuracy)&&Number.isFinite(s.lastGrade.after?.cp)?s.lastGrade:null;activate()}catch(e){message('Impossibile riprendere: '+e.message)}}
try{$('resumeLesson').hidden=!localStorage.getItem('plystreak-training')}catch{}
$('resumeLesson').onclick=resume;$('newLesson').onclick=()=>{if(locked)return;clearGuidance();document.body.classList.remove('training-active','board-focus');$('focusBoard').setAttribute('aria-pressed','false');$('focusBoard').textContent='Concentrati sulla scacchiera';active=false;phase='setup';$('training').hidden=true;$('setup').hidden=false;$('resumeLesson').hidden=false;message('')};
$('trainingBoard').onclick=e=>{const b=e.target.closest('[data-sq]');if(!b||locked||phase!=='user')return;const sq=b.dataset.sq,p=chess.get(sq);if(selected&&chess.moves({square:selected,verbose:true}).some(m=>m.to===sq)){humanMove(selected,sq);return}selected=p?.color===human?sq:null;renderBoard()};
async function undo(){if(locked)return;clearGuidance();undoTurn(chess,human);feedbackHistory=feedbackHistory.filter(x=>x.ply<=chess.history().length);humanDetails=humanDetails.filter(m=>m.ply<chess.history().length);lastGrade=null;lastComment='Prova un’altra idea: la posizione è tornata al tuo turno.';selected=null;result=null;resultPromise=null;steps=[];await run(prepareTurn)}
$('undoTraining').onclick=undo;$('retryMove').onclick=undo;$('retryEngine').onclick=()=>{result=null;run(prepareTurn)};
$('flipTraining').onclick=()=>{flipped=!flipped;renderBoard()};$('stepNext').onclick=()=>{step=Math.min(steps.length-1,step+1);renderDialogue()};$('stepBack').onclick=()=>{step=Math.max(0,step-1);renderDialogue()};
$('askHint').onclick=()=>{if(phase!=='user'||locked||!getSettings().coachHints)return;const h=hintFor(chess,hintStep++);hintSquares=h.squares;$('hintText').textContent=h.text;$('askHint').textContent=hintStep===1?'Un indizio più concreto':'Rileggi l’indizio';renderMarks()};
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{if(locked)return;$('questionAnswer').textContent=coachAnswer(chess,b.dataset.question,human,lastGrade)});
$('exportTraining').onclick=async()=>{const outcome=gameOutcome(chess);chess.setHeader('Result',chess.isCheckmate()?(chess.turn()==='w'?'0-1':'1-0'):outcome?'1/2-1/2':'*');const text=chess.pgn();const file=new File([text],'plystreak-allenamento.pgn',{type:'text/plain'});if(window.Capacitor?.isNativePlatform()){if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]})}catch{}return}const d=document.createElement('dialog'),a=document.createElement('textarea'),b=document.createElement('button');a.value=text;a.readOnly=true;b.textContent='Chiudi';b.onclick=()=>d.remove();d.append('Seleziona e copia il PGN.',a,b);document.body.append(d);d.showModal();return}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('reviewTraining').onclick=()=>{if(locked||!chess.history().length)return;save();try{localStorage.setItem('plystreak-review-import',chess.pgn());localStorage.setItem('plystreak-review-id',sessionId);localStorage.setItem('plystreak-review-side',human);location.href='index.html?training=1&review=auto'}catch{message('Memoria non disponibile. Esporta il PGN e importalo nella revisione.')}};

const presets={milo:{coachName:'Milo',coachTone:'warm',coachFrequency:'all',avatarShape:'round',avatarColor:'sage',avatarEyes:'friendly',avatarAccessory:'none'},astra:{coachName:'Astra',coachTone:'direct',coachFrequency:'all',avatarShape:'cat',avatarColor:'plum',avatarEyes:'focused',avatarAccessory:'glasses'},nox:{coachName:'Nox',coachTone:'quiet',coachFrequency:'errors',avatarShape:'square',avatarColor:'sky',avatarEyes:'happy',avatarAccessory:'headphones'}};
$('coachPreset').value=getSettings().coachPreset;$('coachPreset').onchange=()=>{const key=$('coachPreset').value;if(presets[key])saveSettings({...presets[key],coachPreset:key})};

ENDGAMES.forEach((g,i)=>{const o=document.createElement('option');o.value=i;o.textContent='Finale · '+g.name;$('trainingPosition').append(o)});$('trainingPosition').onchange=()=>{$('endgameGoal').textContent=$('trainingPosition').value===''?'':ENDGAMES[Number($('trainingPosition').value)].goal};
(async()=>{try{const username=localStorage.getItem('plystreak-chess-user');if(!username)return;const report=await getRecord('player-report-'+username,'meta');if(report?.count&&report.theme)$('personalGoal').textContent='Dalle tue ultime partite: '+goals[report.theme]}catch{}})();

$('showThreats').onclick=()=>{if(locked||phase!=='user')return;showThreats=!showThreats;$('showThreats').setAttribute('aria-pressed',String(showThreats));renderMarks()};
$('focusBoard').onclick=()=>{const focused=document.body.classList.toggle('board-focus');$('focusBoard').setAttribute('aria-pressed',String(focused));$('focusBoard').textContent=focused?'Mostra tutti i pannelli':'Concentrati sulla scacchiera'};
